import type { GitService } from '../git/service';
import { ignoreMatcher, isLockfile, readIgnore } from '../review/ignore';

/** Drizzle's migration metadata: rewritten by `db:generate`, never merged by hand. */
const DRIZZLE_META =
  /(^|\/)migrations\/meta\/([^/]*_snapshot\.json|_journal\.json)$/;

/**
 * Whether a path is generated, so a conflict in it is regenerated by the PR's author or agent
 * rather than sent to the model: matched by the target branch's `.orangeignore`, a lockfile, or
 * drizzle migration metadata.
 */
export function generatedMatcher(
  ignoreText: string | null
): (path: string) => boolean {
  const ignored = ignoreMatcher(ignoreText);
  // Lockfiles and drizzle metadata stay generated even if `.orangeignore` negates them.
  return (path) => isLockfile(path) || DRIZZLE_META.test(path) || ignored(path);
}

/** The conflicting paths that are generated, judged by `.orangeignore` on the target tip. */
export async function generatedConflicts(
  git: GitService,
  baseSha: string,
  paths: string[]
): Promise<string[]> {
  if (!paths.length) return [];
  const generated = generatedMatcher(await readIgnore(git, baseSha));
  return paths.filter(generated);
}
